INSERT INTO Language_en_US(Tag,Text) VALUES
 ('TXT_KEY_CWC3_QU_CIV','The Qu — Architects of Flesh'),
 ('TXT_KEY_CWC3_QU_SHORT','The Qu'),
 ('TXT_KEY_CWC3_QU_ADJECTIVE','Qu'),
 ('TXT_KEY_CWC3_QU_LEADER','The First Architect'),
 ('TXT_KEY_CWC3_QU_TRAIT','Divine Reconfiguration'),
 ('TXT_KEY_CWC3_QU_TRAIT_HELP','Gain 1 Biomass from eligible enemy military kills (up to 3 per turn) and 2 Biomass when entering a new era. Store up to 10. Spend 5 Biomass and 1 Population to install one genetic caste in an annexed conquest. Open Genetic Reconfiguration in Additional Information.'),
 ('TXT_KEY_CWC3_QU_DAWN','First Architect, the vaults of Genesis Spire open at your approach. Across the stars, countless civilizations have risen and fallen. You have learned to shape the one material they all carry with them: life itself. Where a conqueror might leave a ruin, your people leave descendants remade to serve a design.[NEWLINE][NEWLINE]The world still calls flesh its own. What form will you give it?'),
 ('TXT_KEY_CWC3_QU_CIV_PEDIA','The Qu are ancient extraterrestrial engineers who regard living forms as mutable. Their four narrow wings and searching tails are the product of their own long history of redesign. From Genesis Spire, the First Architect directs a campaign to reshape the societies the Qu conquer.'),
 ('TXT_KEY_CWC3_QU_CIV_STRATEGY','Build Gene Foundries in established cities. Secure a defensible conquest, let resistance end, and build a Courthouse before spending Biomass. Use Labor Forms for industrial centers, Cognitive Forms for research hubs, and Brood Forms where gross Food is high.'),
 ('TXT_KEY_CWC3_QU_LEADER_PEDIA','The First Architect is the original sovereign of Genesis Spire in this adaptation. The Architect settles arguments over the purpose of a city by choosing the design its people must inhabit.'),
 ('TXT_KEY_CWC3_QU_UNIT','Qu Harvester'),
 ('TXT_KEY_CWC3_QU_UNIT_HELP','Replaces the Rifleman and retains its active statistics and upgrade path. Biological Harvesting grants +15% Combat Strength against already-wounded enemy units and stays through upgrades.'),
 ('TXT_KEY_CWC3_QU_UNIT_PEDIA','Harvester formations follow fractures in an enemy line. A field instrument, guided by the operator’s long prehensile tail, reads the traces left by an earlier engagement.'),
 ('TXT_KEY_CWC3_QU_UNIT_STRATEGY','Soften enemy units before committing Harvesters. Capture ground with their ordinary Rifleman movement and retain the promotion as they upgrade.'),
 ('TXT_KEY_CWC3_QU_PROMOTION','Biological Harvesting'),
 ('TXT_KEY_CWC3_QU_PROMOTION_HELP','+15% Combat Strength when attacking or defending against an enemy unit already wounded at the start of combat. Retained on upgrade.'),
 ('TXT_KEY_CWC3_QU_BUILDING','Gene Foundry'),
 ('TXT_KEY_CWC3_QU_BUILDING_HELP','Replaces the Workshop and retains its effects. Provides +1 base [ICON_RESEARCH] Science at Population 5–9 and +2 at Population 10 or higher.'),
 ('TXT_KEY_CWC3_QU_BUILDING_PEDIA','Within pyramidal banks of living ceramic, the Foundry grows tools, maintains culture vaults, and records experiments carried out by the city’s researchers.'),
 ('TXT_KEY_CWC3_QU_BUILDING_STRATEGY','Build Gene Foundries wherever you would build Workshops. Growing a Foundry city to Population 5 or 10 increases its base Science.'),
 ('TXT_KEY_CWC3_QU_LABOR','Labor Forms'),
 ('TXT_KEY_CWC3_QU_COGNITIVE','Cognitive Forms'),
 ('TXT_KEY_CWC3_QU_BROOD','Brood Forms'),
 ('TXT_KEY_CWC3_QU_LABOR_EFFECT','+12% [ICON_PRODUCTION] Production, −10% [ICON_RESEARCH] Science'),
 ('TXT_KEY_CWC3_QU_COGNITIVE_EFFECT','+12% [ICON_RESEARCH] Science, −10% [ICON_PRODUCTION] Production'),
 ('TXT_KEY_CWC3_QU_BROOD_EFFECT','+15% [ICON_FOOD] Food, −10% [ICON_RESEARCH] Science'),
